import logging
from taf.internal.managedobject import ManagedObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AaShell(ManagedObject):
    """
    ManagedObject interface for AaShell CLI.
    """

    def __init__(self, telnet_connection, **kwargs):
        """
        Create an AaShell.
        """
        super(AaShell, self).__init__(**kwargs)
        self._telnet_connection = telnet_connection
        self.add_prerequisite(telnet_connection)

    @property
    def telnet_connection(self):
        return self._telnet_connection

    def _teardown(self):
        if self._telnet_connection.is_connected:
            self._telnet_connection.write(b"quit" + b"\n")
            self._telnet_connection.read_until(b"Terminating session. Bye ...", timeout=2)

    def _reset_connection(self):
        self.teardown(force=True)
        self.setup()

    def execute(self, command, timeout=None, reconnect=True):
        """
        Execute given command in AaShell session.

        :param bytes command: command need to be executed
        :param int timeout: (optional) timeout value
        :param bool reconnect: (optional) reconnect required if connection is closed, default is True
        :return: bytes, output observed post command execution
        """
        assert command != b"quit", "Call teardown() instead of executing 'quit'"
        logger.debug(
            "Executing command '{command}' with reconnect '{reconnect}'".format(command=command, reconnect=reconnect)
        )
        if not self._telnet_connection.is_connected and reconnect:
            logger.debug("Resetting AaShell setup as telnet connection is down")
            self._reset_connection()
        return self._telnet_connection.execute(command=command, timeout=timeout)
